import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

const TWO_PI = Math.PI * 2;

export async function spinAround(camera: ArcRotateCamera, scene: SceneContext, turns: number): Promise<void> {
  const delta = TWO_PI * Math.abs(turns);
  if (delta === 0) return;
  const startAlpha = camera.alpha;
  const targetAlpha = startAlpha + delta;
  const savedLower = camera.lowerAlphaLimit;
  const savedUpper = camera.upperAlphaLimit;
  const savedInertialAlpha = camera.inertialAlphaOffset;
  // Make sure the transition can reach target without clamping.
  camera.lowerAlphaLimit = -Infinity;
  camera.upperAlphaLimit = Infinity;
  camera.inertialAlphaOffset = 0;
  try {
    await interpolateArcRotateCamera(camera, scene, { alpha: targetAlpha });
    // enforce exact endpoint
    camera.alpha = targetAlpha;
  } finally {
    camera.inertialAlphaOffset = savedInertialAlpha;
    // Restore original limits only if they can contain the start and final values.
    const canRestore =
      (savedLower === undefined || savedLower <= Math.min(startAlpha, targetAlpha)) &&
      (savedUpper === undefined || savedUpper >= Math.max(startAlpha, targetAlpha));
    if (canRestore) {
      camera.lowerAlphaLimit = savedLower;
      camera.upperAlphaLimit = savedUpper;
    } else {
      // Keep relaxed limits to avoid a jump when the promise resolves.
      camera.lowerAlphaLimit = Math.min(savedLower ?? startAlpha, startAlpha, targetAlpha);
      camera.upperAlphaLimit = Math.max(savedUpper ?? targetAlpha, startAlpha, targetAlpha);
    }
  }
}
